def log_throttled(key, event, meta=None, min_interval: float = 30.0):
    now = now_ts()
    k = str(key or "")
    last = float(_LOG_THROTTLE_TS.get(k, 0.0))
    if (now - last) < float(min_interval):
        return
    _LOG_THROTTLE_TS[k] = now
    log_runtime("info", f"THROTTLED: {event}", **(meta or {}))

