_AEE_TUNE_APPLIED_LAST: Dict[str, Dict[str, str]] = {}  # "{trade_id}:{leg}" -> {"policy","tune_hash","state_key","source_key"}
_TEACHER_EMIT_SKIPPED_INCOMPLETE = 0
_TEACHER_EMIT_EMITTED = 0
