def normalize_pair(pair: str) -> str:
    p = str(pair or "").strip().upper()
    if not p:
        return ""
    p = p.replace("-", "_").replace("/", "_")
    if "_" not in p and len(p) == 6 and p.isalpha():
        p = f"{p[:3]}_{p[3:]}"
    return p

def normalize_granularity(gran: str) -> str:
    return str(gran or "").strip().upper()

def normalize_oanda_env(env: str) -> str:
    e = str(env or "").strip().lower()
    if e in ("practice", "fxpractice", "demo", "paper", "test"):
        return "practice"
    if e in ("live", "fxtrade", "prod", "production"):
        return "live"
    return ""


def extract_nav_from_account(acct_sum: dict) -> Tuple[float, str]:
    """Parse NAV (netAssetValue) from account summary response.

    OANDA returns netAssetValue as the current portfolio value.
    Falls back to balance if NAV not available.
    """
    if not isinstance(acct_sum, dict):
        return float("nan"), "invalid"

    account_obj = acct_sum.get("account")
    if isinstance(account_obj, dict):
        # Try NAV first (most accurate for current portfolio value)
        if "netAssetValue" in account_obj:
            try:
                return float(account_obj["netAssetValue"]), "nested_account_nav"
            except Exception:
                pass
        # Fallback to balance
        if "balance" in account_obj:
            try:
                return float(account_obj["balance"]), "nested_account_balance"
            except Exception:
                pass

    # Top level fallbacks
    if "netAssetValue" in acct_sum:
        try:
            return float(acct_sum["netAssetValue"]), "top_level_nav"
        except Exception:
            pass
    if "balance" in acct_sum:
        try:
            return float(acct_sum["balance"]), "top_level_balance"
        except Exception:
            pass

    return float("nan"), "missing"


def extract_margin_available(acct_sum: dict) -> Tuple[float, str]:
    """Parse marginAvailable from account summary response across known shapes."""
    if not isinstance(acct_sum, dict):
        return float("nan"), "invalid"
    account_obj = acct_sum.get("account")
    if isinstance(account_obj, dict) and "marginAvailable" in account_obj:
        val = account_obj.get("marginAvailable")
        try:
            return float(val if val is not None else 0.0), "nested_account"
        except Exception:
            return float("nan"), "nested_account_invalid"
    if "marginAvailable" in acct_sum:
        val = acct_sum.get("marginAvailable")
        try:
            return float(val if val is not None else 0.0), "top_level"
        except Exception:
            return float("nan"), "top_level_invalid"
    return float("nan"), "missing"

