    breakout_dir: str = ""

    box_hi: float = float("nan")
    box_lo: float = float("nan")
    box_atr: float = float("nan")
    wr: float = float("nan")
    wr_prev: float = float("nan")
    m_norm: float = float("nan")
    atr_exec: float = float("nan")
    atr_long: float = float("nan")
