    def track_pulse_trigger(self, pair: str, pulse_z: float):
        """Track pulse trigger for latency measurement"""
        self.pulse_triggers[pair] = {
            'timestamp': time.time(),
            'pulse_z': pulse_z,
            'pair': pair
        }
        self.forensic_metrics['pulse_momentum_engine']['total_pulses'] += 1

