                    if not candles or len(candles) < window:
                        continue
                    # Compute window hash
                    candle_bytes = json.dumps(candles, sort_keys=True).encode()
                    window_hash = hashlib.sha256(candle_bytes).hexdigest()
                    atr_val = compute_atr_price(candles, 14)
